function sbuAnalysisRows(){const previous=activeSbu,year=+state.year,selected=ids().slice(),previousIds=ids,out=[];try{ids=()=>selected;for(const [id,sbu]of Object.entries(portfolio.sbus)){activate(id);state.year=year;const p=performanceMeasures(),c=cashMetrics(),actualCount=selected.filter(m=>rv(31,[m])!==null).length;out.push({id,name:sbu.name,code:sbu.code||sbu.name,sales:rv(31),budget:rv(31,selected,'Budget'),profit:rv(67),profitBudget:rv(67,selected,'Budget'),gross:rv(46),operating:rv(51),contribution:rv(41),salesBeforeCommission:rv(29),volume:rv(19),volumeBudget:rv(19,selected,'Budget'),production:rv(12),capacity:rv(5),materials:rv(33),cost:p.allCost,margin:p.margin,roce:p.roce,cover:p.cover,cash:c.cash,ocf:c.ocf,afterCapex:c.afterCapex,nwc:c.nwc,currentRatio:c.currentRatio,exInvestmentRatio:c.exInvestmentRatio,netDebt:c.netDebt,debt:c.debt,receivables:fv('balance',18),inventory:fv('balance',17),investment:c.investment,liabilities:c.liabilities,actualCount,selectedCount:selected.length,months:selected.map(m=>({label:periodMonthLabel(m),sales:rv(31,[m]),profit:rv(67,[m]),ocf:fv('cashflow',13,m)}))});}}finally{ids=previousIds;activate(previous);state.year=year;}return out;}
function sbuLink(r){return `<button data-open-sbu="${esc(r.id)}">${esc(r.name)}${r.id===activeSbu?' · Active':''}</button>`;}
function sbuComparisonBars(rows,key,format=money){const max=Math.max(1,...rows.map(r=>Math.abs(r[key]??0)));return rows.map(r=>`<button class="sbu-analysis-bar" data-open-sbu="${esc(r.id)}" title="${esc(r.name)}: ${format(r[key])}" aria-label="Open ${esc(r.name)}; ${key}: ${format(r[key])}"><span>${esc(r.code)}</span><span class="sbu-analysis-track">${r[key]===null?'':`<i style="width:${Math.abs(r[key])/max*100}%;background:${r[key]<0?'#bd4655':'#087f8c'}"></i>`}</span><strong>${format(r[key])}</strong></button>`).join('');}
groupView=function(){const rows=sbuAnalysisRows(),valid=rows.filter(r=>r.sales!==null),best=rows.filter(r=>r.margin!==null).sort((a,b)=>b.margin-a.margin)[0],losses=rows.filter(r=>r.profit!==null&&r.profit<0),cashPositive=rows.filter(r=>r.ocf!==null&&r.ocf>0),cashKnown=rows.filter(r=>r.ocf!==null),profKnown=rows.filter(r=>r.profit!==null);const leaders=rows.filter(r=>r.sales!==null).sort((a,b)=>b.sales-a.sales),insights=[];if(leaders.length)insights.push([leaders[0].name,'Largest reported net sales',money(leaders[0].sales)+' '+unit(),'Review its sales mix, margin and cash conversion before judging overall performance.']);if(best)insights.push([best.name,'Highest available net margin',pct(best.margin),'Compare margin quality alongside operating cash and capital employed.']);for(const r of rows){if(r.profit<0&&r.profit!==null)insights.push([r.name,'Loss position',money(r.profit)+' '+unit(),'Review profit drivers and break-even targets.']);if(r.sales!==null&&r.budget>0&&r.sales<r.budget)insights.push([r.name,'Sales below budget',pct(percent(r.sales,r.budget))+' achieved','Examine volume, selling value and product mix.']);if(r.nwc!==null&&r.nwc<0)insights.push([r.name,'Negative working capital',money(r.nwc)+' '+unit(),'Review liquidity, current funding and payment commitments.']);if(r.ocf!==null&&r.profit>0&&r.ocf<r.profit)insights.push([r.name,'Cash generation below profit',money(r.ocf)+' '+unit()+' operating cash','Review the formal cash statement; do not infer a working-capital cash cause without a bridge.']);}return `<div class="notice">${esc(period())} · ${unit()}. Every SBU is evaluated over the same selected months. These comparisons are not consolidated group accounts; intercompany eliminations are not available. Select an SBU name or bar to open its performance review.</div><div class="cards">${card('SBUs in analysis',rows.length,valid.length+' with complete selected-period sales')}${card('Highest available net margin',best?pct(best.margin):'—',best?esc(best.name):'No comparable data')}${card('SBUs reporting losses',profKnown.length?losses.length:'—',profKnown.length+' with reported profit data')}${card('Positive operating cash',cashKnown.length?cashPositive.length:'—',cashKnown.length+' with complete cash-flow data')}</div><div class="grid">`+panel('Net sales comparison','Bar length shows absolute amount; negative values are red. '+unit(),sbuComparisonBars(rows,'sales'))+panel('Net profit / loss comparison','Rankings describe selected reported results, not overall business quality. '+unit(),sbuComparisonBars(rows,'profit'))+'</div>'+panel('Profitability & budget achievement','Same selected period. Missing figures remain blank.',table(['SBU','Net sales','Sales budget','Sales achieved','Sales variance','NPAT','Profit budget','Profit variance','Net margin'],rows.map(r=>[sbuLink(r),money(r.sales),money(r.budget),pct(percent(r.sales,r.budget)),money(sub(r.sales,r.budget)),money(r.profit),money(r.profitBudget),money(sub(r.profit,r.profitBudget)),pct(r.margin)])))+panel('Operating efficiency & cost intensity','Company ratios use sales tonnes. Different product mixes and sector economics limit direct per-tonne comparability.',table(['SBU','Sales MT','Volume budget achieved','Production MT','Capacity used','Contribution %','Gross margin','Operating margin','Materials / sales','All-in cost / sales MT'],rows.map(r=>[sbuLink(r),num(r.volume,1),pct(percent(r.volume,r.volumeBudget)),num(r.production,1),pct(percent(r.production,r.capacity)),pct(percent(r.contribution,r.salesBeforeCommission)),pct(percent(r.gross,r.sales)),pct(percent(r.operating,r.sales)),pct(percent(r.materials,r.salesBeforeCommission)),num(ratio(r.cost,r.volume),0)])))+panel('Cash generation & liquidity','Cash flows cover the selected months; balance-sheet values use the closing month.',table(['SBU','Operating cash','Cash after PPE/CWIP','OCF / sales','Closing cash','Net working capital','Current ratio','Current ratio excl. investments'],rows.map(r=>[sbuLink(r),money(r.ocf),money(r.afterCapex),pct(percent(r.ocf,r.sales)),money(r.cash),money(r.nwc),times(r.currentRatio),times(r.exInvestmentRatio)])))+panel('Capital, funding & working-capital exposure','ROCE is not annualized. Net debt deducts cash only; short-term investments are not assumed liquid.',table(['SBU','Inventory','Receivables','Short-term investments','Bank / lease debt','Net bank / lease debt','Interest cover','Period ROCE'],rows.map(r=>[sbuLink(r),money(r.inventory),money(r.receivables),money(r.investment),money(r.debt),money(r.netDebt),times(r.cover),pct(r.roce)])))+`<div class="grid">`+panel('Monthly net sales across SBUs','Same months for every series · '+unit(),reviewChart('SBU net sales',rows.map(r=>({name:r.code,values:r.months.map(m=>m.sales)})),rows[0]?.months.map(m=>m.label)||[]))+panel('Monthly net profit across SBUs','Net profit after tax · '+unit(),reviewChart('SBU net profit',rows.map(r=>({name:r.code,values:r.months.map(m=>m.profit)})),rows[0]?.months.map(m=>m.label)||[]))+'</div>'+panel('Management review priorities','Rule-based signals drawn only from reported values; suggested review actions are not assigned tasks.',insights.length?table(['SBU','Signal','Evidence','Review action'],insights.map(r=>r.map(esc))):empty('Insufficient evidence for review signals'))+panel('Data completeness','A complete sales period does not establish completeness of every other metric.',table(['SBU','Actual sales months','Selected months','Sales coverage','Cash-flow coverage'],rows.map(r=>[sbuLink(r),r.actualCount,r.selectedCount,r.actualCount===r.selectedCount?'Complete':'Incomplete',r.ocf===null?'Incomplete / unavailable':'Complete'])))+`<p class="source">Missing periods are not treated as zero. Rankings exclude unavailable values. Differences in business scale, product mix and investment structure should be considered before setting cross-SBU targets.</p>`;};
